def find_topmost_carpet(n, carpets, point):
    # Create a set to store the ids of the carpets that cover the point
    covered_carpets = set()

    # Iterate through the carpets and check if each carpet covers the point
    for i in range(n):
        carpet = carpets[i]
        if carpet[0] <= point[0] <= carpet[0] + carpet[2] and carpet[1] <= point[1] <= carpet[1] + carpet[3]:
            covered_carpets.add(i)

    # If no carpet covers the point, return -1
    if not covered_carpets:
        return -1

    # Find the topmost carpet by comparing the y-coordinates of the covered carpets
    topmost_carpet = None
    for carpet in covered_carpets:
        if topmost_carpet is None or carpets[carpet][1] > carpets[topmost_carpet][1]:
            topmost_carpet = carpet

    # Return the id of the topmost carpet
    return topmost_carpet

