def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a dictionary to store the number of chatting pairs that can be separated by each aisle
    aisle_dict = {}
    for i in range(1, M + 1):
        for j in range(1, N + 1):
            aisle_dict[(i, j)] = 0

    # Count the number of chatting pairs that can be separated by each aisle
    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        for i in range(1, M + 1):
            for j in range(1, N + 1):
                if (x1 < i < x2 or x1 > i > x2) and (y1 < j < y2 or y1 > j > y2):
                    aisle_dict[(i, j)] += 1

    # Select the most effective positions for the aisles
    row_aisles = []
    col_aisles = []
    for i in range(K):
        max_value = max(aisle_dict, key=aisle_dict.get)
        row_aisles.append(max_value)
        for j in range(1, N + 1):
            if (max_value[0], j) in aisle_dict:
                del aisle_dict[(max_value[0], j)]
    for i in range(L):
        max_value = max(aisle_dict, key=aisle_dict.get)
        col_aisles.append(max_value)
        for j in range(1, M + 1):
            if (j, max_value[1]) in aisle_dict:
                del aisle_dict[(j, max_value[1])]

    # Return the row and column indices of the aisles
    return ' '.join(str(row) for row in row_aisles), ' '.join(str(col) for col in col_aisles)

