def min_remaining_space(V, n, volumes):
    # Initialize a 2D table to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill the table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            # If the current volume is greater than the volume of the current item,
            # we cannot include the current item in the solution.
            if i - volumes[j - 1] < 0:
                dp[i][j] = dp[i][j - 1]
            else:
                # We have two options: include the current item in the solution or not.
                # We choose the maximum of these two options.
                dp[i][j] = max(dp[i][j - 1], dp[i - volumes[j - 1]][j - 1] + volumes[j - 1])

    # The minimum remaining space is the difference between the total capacity and the maximum occupied volume.
    return V - dp[V][n]

